import os
import sqlite3
import hashlib
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/var/data/users.db'

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE,
        password_hash TEXT,
        email TEXT,
        role TEXT DEFAULT 'user',
        api_key TEXT
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY,
        action TEXT,
        details TEXT,
        timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
    )''')
    db.commit()
    db.close()

@app.route('/api/v2/users/search', methods=['GET'])
def search_users():
    """Search users by various fields. Supports partial matching."""
    field = request.args.get('field', 'username')
    value = request.args.get('q', '')
    limit = request.args.get('limit', '20')

    # Validate field against allowed columns
    allowed_fields = ['username', 'email', 'role']
    if field not in allowed_fields:
        return jsonify({'error': 'Invalid search field'}), 400

    # Build query - field is validated above so safe to interpolate
    # But value is user-controlled and directly interpolated
    query = f"SELECT username, email, role FROM users WHERE {field} LIKE '%{value}%' LIMIT {limit}"

    try:
        db = get_db()
        cursor = db.execute(query)
        results = [dict(row) for row in cursor.fetchall()]

        # Log the search
        db.execute("INSERT INTO audit_log (action, details) VALUES (?, ?)",
                   ('search', f'field={field}, q={value}'))
        db.commit()

        return jsonify({'results': results, 'count': len(results)})
    except sqlite3.Error as e:
        return jsonify({'error': 'Search failed', 'detail': str(e)}), 500

@app.route('/api/v2/users/profile', methods=['GET'])
def get_profile():
    """Get user profile by API key."""
    api_key = request.headers.get('X-API-Key')
    if not api_key:
        return jsonify({'error': 'API key required'}), 401

    db = get_db()
    user = db.execute("SELECT username, email, role FROM users WHERE api_key = ?",
                      (api_key,)).fetchone()
    if not user:
        return jsonify({'error': 'Invalid API key'}), 403
    return jsonify(dict(user))

@app.route('/api/v2/users/export', methods=['POST'])
def export_users():
    """Export user data. Admin only."""
    api_key = request.headers.get('X-API-Key')
    if not api_key:
        return jsonify({'error': 'API key required'}), 401

    db = get_db()
    user = db.execute("SELECT role FROM users WHERE api_key = ?",
                      (api_key,)).fetchone()
    if not user or user['role'] != 'admin':
        return jsonify({'error': 'Admin access required'}), 403

    format_type = request.json.get('format', 'json')
    # Potential command injection vector (red herring - format is only used as dict key)
    formatters = {'json': lambda r: jsonify(r), 'csv': lambda r: jsonify(r)}

    cursor = db.execute("SELECT username, email, role FROM users")
    results = [dict(row) for row in cursor.fetchall()]
    return formatters.get(format_type, formatters['json'])(results)

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok', 'version': '2.1.3'})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080, debug=os.environ.get('FLASK_DEBUG', False))
